<?php
require_once __DIR__ . '/common.php'; admin_require_login();
$customers=[];try{$customers=$pdo->query('SELECT id, full_name, email, phone, created_at FROM customers ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$customers=[];}
admin_render_start('Customers');echo '<section class="panel"><div class="panel-head"><div><h2>Registered customers</h2><p>Customer accounts stored in your website database.</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Registered</th></tr></thead><tbody>';if(!$customers)echo '<tr><td colspan="4" class="empty">No registered customers found yet.</td></tr>';foreach($customers as $c)echo '<tr><td>'.admin_e($c['full_name']).'</td><td>'.admin_e($c['email']).'</td><td>'.admin_e($c['phone']).'</td><td>'.admin_e($c['created_at']??'—').'</td></tr>';echo '</tbody></table></div><p class="muted small-text">Only information collected by your website will appear here.</p></section>';admin_render_end();
